'use strict';
// Only renderer/src is maintained. Generated files are disposable build output.
const fs = require('node:fs');
const path = require('node:path');
const root = path.resolve(__dirname, '..');
const design = path.join(root, 'renderer/src');
const output = path.join(root, 'renderer/generated');
fs.mkdirSync(output, { recursive: true });
const html = fs.readFileSync(path.join(design, 'shell.html'), 'utf8');
if (/<script\b|<dialog\b|示例数据/.test(html)) throw new Error('Desktop shell must contain markup only, without prototype records.');
fs.writeFileSync(path.join(output, 'shell.js'), '// Generated by scripts/build-desktop-assets.cjs. No example business records.\nwindow.DNSDesktopMarkup = ' + JSON.stringify(html) + ';\n');
let css = fs.readFileSync(path.join(design, 'workspace.css'), 'utf8');
css = css.replace(/^@charset[^;]*;\s*/, '').replace(':root{', ':scope{')
  .replace('html,body{height:100%;margin:0}', ':scope{margin:0}')
  .replace('body{font-family:', ':scope{font-family:');
fs.writeFileSync(path.join(output, 'workspace.css'), '/* Generated desktop chrome, scoped away from existing business forms. */\n@scope (#desktop-app) {\n' + css + '\n}\n');
console.log('Built Electron-owned desktop markup and scoped styles.');
